\begin{tikzpicture}[x={(1.35cm,0cm)},y={(0.48cm,0.42cm)},z={(0cm,0.65cm)},line width=0.8pt]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\definecolor{hiddenRed}{HTML}{EF6068}
% Obscured bottom rods parallel to the length.
\foreach \yy in {1,2}{\foreach \xx in {0,1,2}{\draw[hiddenRed,dashed] (\xx,\yy,0)--({\xx+1},\yy,0);}}
% Obscured bottom rods parallel to the width.
\foreach \xx in {0,1,2}{\foreach \yy in {0,1}{\draw[hiddenRed,dashed] (\xx,\yy,0)--(\xx,{\yy+1},0);}}
% Obscured vertical rods behind the front face and inside the right silhouette.
\foreach \xx in {0,1,2}{\foreach \yy in {1,2}{\draw[hiddenRed,dashed] (\xx,\yy,0)--(\xx,\yy,1);}}
% Top lattice: all unit rods remain explicit.
\foreach \yy in {0,1,2}{\foreach \xx in {0,1,2}{\draw[black] (\xx,\yy,1)--({\xx+1},\yy,1);}}
\foreach \xx in {0,1,2,3}{\foreach \yy in {0,1}{\draw[black] (\xx,\yy,1)--(\xx,{\yy+1},1);}}
% Front face, including its bottom rods.
\foreach \xx in {0,1,2}{\draw[black] (\xx,0,0)--({\xx+1},0,0);}
\foreach \xx in {0,1,2,3}{\draw[black] (\xx,0,0)--(\xx,0,1);}
% Right face and its silhouette.
\foreach \yy in {0,1}{\draw[black] (3,\yy,0)--(3,{\yy+1},0);}
\foreach \yy in {1,2}{\draw[black] (3,\yy,0)--(3,\yy,1);}
\end{tikzpicture}
